insert into public.events(id,title,event_date,description,type,venue,cover_image_url) values('last-login-2026','THE LAST LOGIN — 2026 Networking','2026-10-30','2026 оны намрын тэнхимийн өдөрлөг. Багш, оюутан, төгсөгчдийн уулзалт, танилцах үйл ажиллагаа, хөгжилтэй тоглоом.','Networking','СЭЗИС, 4С','/images/last-login.webp') on conflict (id) do nothing;
insert into public.events(id,title,event_date,description,type,venue,cover_image_url) values('password-2026','Password Day 2026','2026-05-08','Кибер аюулгүй байдлын өдөрлөг: цахим гэмт хэргийн бодит кейс, аудитын байгууллагын мэргэжилтний зөвлөгөө, хөгжөөнт тоглоом, шагналтай тэмцээн.','Кибер аюулгүй байдал','СЭЗИС, 4С • 11:00–12:00','/images/password-2026.webp') on conflict (id) do nothing;
insert into public.events(id,title,event_date,description,type,venue,cover_image_url) values('nokhorlol-2026','Нөхөрлөл 2026','2026-04-18','Оюутан, багш, төгсөгчдийн уламжлалт спортын өдөрлөг. Волейбол, буухиа тэмцээн болон хамт олны дурсамжит мөчүүд.','Спорт','СЭЗИС спорт заал • 09:00','/images/nokhorlol-2026.webp') on conflict (id) do nothing;
insert into public.events(id,title,event_date,description,type,venue,cover_image_url) values('creators-2025','Бүтээлийн уралдаан 2025','2025-04-24','Мэдээллийн системийн оюутнуудын бүтээлтэй танилцах уламжлалт уралдаан, үзэсгэлэн.','Оюутны бүтээл','СЭЗИС, С байрны 4-р давхар','/images/creators-2025.webp') on conflict (id) do nothing;
insert into public.events(id,title,event_date,description,type,venue,cover_image_url) values('password-2025','Password Day 2025','2025-05-01','“Password equals power” кибер аюулгүй байдлын өдөрлөг.','Кибер аюулгүй байдал','СЭЗИС, 4С • 12:00','/images/password-2025.webp') on conflict (id) do nothing;
insert into public.events(id,title,event_date,description,type,venue,cover_image_url) values('networking-2024','ISMD Networking 2024','2024-11-09','Багш, төгсөгч, оюутнуудын мэдлэг туршлага, инээд хөөр, нөхөрлөлөөр дүүрэн networking өдөрлөг.','Networking','СЭЗИС','/images/networking-2024.webp') on conflict (id) do nothing;
