insert into public.milestones(year,title,description) values('1964','Эхлэл — тооцоолох кабинет','“Механикжсан цахилгаан тооцооны хичээлийн кабинет” байгуулагдаж, 8 тооцоолох машинтайгаар үйл ажиллагаагаа эхлүүлэв.') on conflict (year,title) do nothing;
